// Writes third_party/RUST-AND-NPM-DEPENDENCIES.txt: the licence notices of every Rust crate linked into the
// Windows release binary and every npm package bundled into dist/. Rerun before each release:
//   node third_party/dependency-licenses.mjs
// Needs cargo and pnpm (with node_modules installed); reads only the cargo registry and node_modules.
import { execSync } from "node:child_process";
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const run = (cmd) => execSync(cmd, { cwd: root, maxBuffer: 1 << 28 }).toString();
const LICENCE = /^(licen[cs]e|copying|notice|copyright|unlicense)/i;

// The licence files at the package root; a package with none there (rquickjs-sys keeps QuickJS's in quickjs/)
// gets those one folder down.
function licenceTexts(dir, sub = "") {
  const names = readdirSync(join(dir, sub)).sort();
  const files = names.filter((f) => LICENCE.test(f) && statSync(join(dir, sub, f)).isFile());
  if (!files.length && !sub) return names.filter((f) => statSync(join(dir, f)).isDirectory()).flatMap((d) => licenceTexts(dir, d));
  return files.map((f) => ({ file: sub ? `${sub}/${f}` : f, text: readFileSync(join(dir, sub, f), "utf8").replace(/\r\n/g, "\n").trim() }));
}

// Rust: the crates reachable from inkwell through normal (linked) dependencies on Windows; build-script
// dependencies and proc macros run at build time and are not in the binary. Path crates (inkwell itself and
// the vendored mupdf/mupdf-sys) are covered by THIRD-PARTY-NOTICES.txt.
const meta = JSON.parse(
  run("cargo metadata --format-version 1 --locked --filter-platform x86_64-pc-windows-msvc --manifest-path src-tauri/Cargo.toml"),
);
const pkgs = new Map(meta.packages.map((p) => [p.id, p]));
const nodes = new Map(meta.resolve.nodes.map((n) => [n.id, n]));
const linked = new Set();
const todo = [meta.resolve.root];
while (todo.length) {
  const id = todo.pop();
  if (linked.has(id)) continue;
  linked.add(id);
  for (const d of nodes.get(id).deps) {
    const normal = d.dep_kinds.some((k) => k.kind === null);
    const macro = pkgs.get(d.pkg).targets.some((t) => t.kind.includes("proc-macro"));
    if (normal && !macro) todo.push(d.pkg);
  }
}
const rust = [...linked]
  .map((id) => pkgs.get(id))
  .filter((p) => p.source)
  .map((p) => ({ name: p.name, version: p.version, license: p.license ?? `see ${p.license_file}`, url: p.repository ?? "", dir: join(p.manifest_path, "..") }));

// npm: the production dependencies vite bundles into dist/.
const npm = Object.values(JSON.parse(run("pnpm licenses list --prod --json")))
  .flat()
  .flatMap((p) => p.versions.map((v, i) => ({ name: p.name, version: v, license: p.license, url: p.homepage ?? "", dir: p.paths[i] })));

const out = [
  "Licences of the Rust crates and npm packages in Inkwell",
  "",
  "Generated by third_party/dependency-licenses.mjs. Each entry names a package, its licence and the licence",
  "files it ships, verbatim. A text shared by several packages is printed once and referred to after that.",
  "",
];
const seen = new Map();
for (const [title, list] of [["Rust crates", rust], ["npm packages", npm]]) {
  out.push("=".repeat(100), title, "=".repeat(100), "");
  for (const p of list.sort((a, b) => a.name.localeCompare(b.name) || a.version.localeCompare(b.version))) {
    out.push(`${p.name} ${p.version}`, `  Licence: ${p.license}`);
    if (p.url) out.push(`  Source: ${p.url}`);
    const texts = licenceTexts(p.dir);
    if (!texts.length) out.push("  (ships no licence file; the standard text of the licence above applies)");
    for (const t of texts) {
      const first = seen.get(t.text);
      if (first) {
        out.push(`  ${t.file}: same text as ${first}`);
        continue;
      }
      seen.set(t.text, `${t.file} of ${p.name} ${p.version}`);
      out.push(`  ${t.file}:`, "", t.text, "");
    }
    out.push("-".repeat(100), "");
  }
}
writeFileSync(join(root, "third_party", "RUST-AND-NPM-DEPENDENCIES.txt"), out.join("\n"));
console.log(`${rust.length} crates, ${npm.length} npm packages`);
